// FCS reader vs an independent implementation (flowio 1.4.0, BSD-3; oracle
// generated by scripts/oracles/fcs_flowio.py) plus malformed-input handling.
import { describe, expect, it } from 'vitest';
import { AppError } from '../src/core/errors';
import { parseFcs } from '../src/core/fcs';
import oracle from './oracles/fcs_flowio.json';
import { haveFixtures, readBytes } from './fixtures';

const paths: Record<string, string> = {
  'data1.fcs': 'gate_ref/data1.fcs',
  'test_data_2d_01.fcs': 'test_data_2d_01.fcs',
  'test_data_diamond_01.fcs': 'simple_diamond_example/test_data_diamond_01.fcs',
  '100715.fcs': '100715.fcs',
  'test_comp_example.fcs': 'test_comp_example.fcs',
  '101_DEN084Y5_15_E03_009_clean.fcs': '8_color_data_set/fcs_files/101_DEN084Y5_15_E03_009_clean.fcs',
  'index_sorted_example.fcs': 'index_sorted/index_sorted_example.fcs',
};

describe.skipIf(!haveFixtures)('FCS decode matches flowio (raw channel values)', () => {
  for (const [name, o] of Object.entries(oracle as Record<string, { count: number; names: string[]; sums: number[]; first: number[][]; last: number[] }>)) {
    it(name, () => {
      const f = parseFcs(readBytes(paths[name]), { raw: true });
      expect(f.eventCount).toBe(o.count);
      expect(f.channels.map((c) => c.name)).toEqual(o.names);
      f.data.forEach((col, c) => {
        // float32 sums: relative 1e-9 covers summation-order differences
        let s = 0;
        for (const v of col) s += v;
        expect(Math.abs(s - o.sums[c])).toBeLessThanOrEqual(1e-9 * Math.max(1, Math.abs(o.sums[c])));
        for (let r = 0; r < 3; r++) expect(col[r]).toBe(o.first[r][c]);
        expect(col[col.length - 1]).toBe(o.last[c]);
      });
    });
  }
  it('test_comp_example.fcs: off-by-one DATA offset is detected and reported', () => {
    const f = parseFcs(readBytes(paths['test_comp_example.fcs']));
    expect(f.warnings.join(' ')).toMatch(/DATA offsets|differ/);
  });
  it('noncompliant offset examples parse with a warning', () => {
    for (const p of ['noncompliant/data_start_offset_discrepancy_example.fcs', 'noncompliant/data_stop_offset_discrepancy_example.fcs']) {
      const f = parseFcs(readBytes(p));
      expect(f.eventCount).toBeGreaterThan(0);
      expect(f.warnings.length).toBeGreaterThan(0);
    }
  });
  it('applies $PnG and $PnE when not raw (data1.fcs: FSC-H gain 3.67, FL1-H log 4 decades)', () => {
    const raw = parseFcs(readBytes(paths['data1.fcs']), { raw: true });
    const sc = parseFcs(readBytes(paths['data1.fcs']));
    const fsc = raw.channels.findIndex((c) => c.name === 'FSC-H');
    const fl1 = raw.channels.findIndex((c) => c.name === 'FL1-H');
    expect(sc.data[fsc][0]).toBeCloseTo(raw.data[fsc][0] / 3.67, 12);
    // 10^(4 * x / range), range from $P3R
    const r = raw.channels[fl1].range;
    expect(sc.data[fl1][5]).toBeCloseTo(10 ** ((4 * raw.data[fl1][5]) / r), 9);
  });
});

function makeFcs(text: string, data: Uint8Array, version = 'FCS3.1'): Uint8Array {
  const textStart = 58;
  const textBytes = new TextEncoder().encode(text);
  const dataStart = textStart + textBytes.length;
  const pad = (n: number) => String(n).padStart(8, ' ');
  const header = `${version}    ${pad(textStart)}${pad(dataStart - 1)}${pad(dataStart)}${pad(dataStart + data.length - 1)}${pad(0)}${pad(0)}`;
  const out = new Uint8Array(dataStart + data.length);
  out.set(new TextEncoder().encode(header), 0);
  out.set(textBytes, textStart);
  out.set(data, dataStart);
  return out;
}

describe('synthetic FCS files', () => {
  const f32 = (vals: number[], little = true) => {
    const b = new Uint8Array(vals.length * 4);
    const dv = new DataView(b.buffer);
    vals.forEach((v, i) => dv.setFloat32(i * 4, v, little));
    return b;
  };
  const kw = (extra = '') => `/$BYTEORD/1,2,3,4/$DATATYPE/F/$MODE/L/$PAR/2/$TOT/2/$P1N/FSC-A/$P1B/32/$P1R/1024/$P1S/Forward//Scatter/$P2N/FL1-A/$P2B/32/$P2R/1024/${extra}`;
  it('decodes float data, escaped delimiters and labels', () => {
    const f = parseFcs(makeFcs(kw(), f32([1.5, 2, 3, -4])));
    expect(f.data[0]).toEqual(Float64Array.from([1.5, 3]));
    expect(f.data[1]).toEqual(Float64Array.from([2, -4]));
    expect(f.channels[0].label).toBe('Forward/Scatter');
  });
  it('decodes big-endian 16-bit integers with range masking', () => {
    const b = new Uint8Array([0x00, 0x05, 0xff, 0xff]);
    const f = parseFcs(makeFcs('/$BYTEORD/4,3,2,1/$DATATYPE/I/$MODE/L/$PAR/1/$TOT/2/$P1N/A/$P1B/16/$P1R/1024/', b));
    expect([...f.data[0]]).toEqual([5, 1023]);
  });
  const code = (fn: () => unknown) => {
    try {
      fn();
    } catch (e) {
      return (e as AppError).code;
    }
    return 'no error';
  };
  it('rejects non-FCS input', () => expect(code(() => parseFcs(new TextEncoder().encode('hello world'.repeat(10))))).toBe('FCS_BAD_HEADER'));
  it('rejects truncated data', () => expect(code(() => parseFcs(makeFcs(kw(), f32([1, 2]))))).toBe('FCS_TRUNCATED'));
  it('rejects missing required keywords', () => expect(code(() => parseFcs(makeFcs('/$BYTEORD/1,2,3,4/$DATATYPE/F/$PAR/1/$TOT/1/', f32([1]))))).toBe('FCS_MISSING_KEYWORD'));
  it('rejects histogram mode', () => expect(code(() => parseFcs(makeFcs(kw('$MODE/H/').replace('$MODE/L/', ''), f32([1, 2, 3, 4]))))).toBe('FCS_UNSUPPORTED'));
  it('rejects ASCII datatype', () => expect(code(() => parseFcs(makeFcs(kw().replace('$DATATYPE/F', '$DATATYPE/A'), f32([1, 2, 3, 4]))))).toBe('FCS_UNSUPPORTED'));
  it('rejects mixed byte order', () => expect(code(() => parseFcs(makeFcs(kw().replace('1,2,3,4', '3,4,1,2'), f32([1, 2, 3, 4]))))).toBe('FCS_UNSUPPORTED'));
  it('falls back to Latin-1 for non-UTF-8 TEXT with a warning', () => {
    const t = new TextEncoder().encode(kw('$CYT/X/'));
    const raw = makeFcs(kw('$CYT/X/'), f32([1, 2, 3, 4]));
    raw[58 + t.length - 2] = 0xe9; // invalid UTF-8 byte in a value
    const f = parseFcs(raw);
    expect(f.warnings.join(' ')).toMatch(/Latin-1/);
  });
});
